return (function(){
  const r = (x,n=2)=> (Math.round(x*10**n)/10**n).toLocaleString('en-US',{maximumFractionDigits:n});
  const out = [];
  const P = (label, val, expect) => out.push(`${label}: ${r(val)}${expect!==undefined? (Math.abs(val-expect)<0.51? ' OK (doc: '+expect+')' : '  MISMATCH doc='+expect) : ''}`);

  // --- proposal after tax
  const costs = 1100000*0.06;
  const gain = 1100000 - costs - 300000;            // 734,000
  const wifeTax_prop = (gain-250000)*0.188;         // NIIT applied per engagement convention
  P('selling costs', costs, 66000); P('house gain', gain, 734000);
  P('proposal her house tax', wifeTax_prop, 90992);
  P('house net (keep scenario)', 700000-costs-wifeTax_prop, 543008);
  const wifeP = 700000-costs-wifeTax_prop+50000+20000;
  const husbP = 400000*0.76 + (300000-0.15*80000) + 50000+20000;
  P('proposal wife', wifeP, 613008); P('proposal husband', husbP, 662000);
  P('gap', husbP-wifeP, 48992);
  P('ratio %', 100*wifeP/husbP, 92.6); P('months of her gross', (husbP-wifeP)/6000, 8.17);
  P('401k@12%', 770000-400000*0.12 -12000+50000+20000 -613008 +613008, 710000); // check 710,000
  P('401k@32%', 300000-0.15*80000+50000+20000+400000*0.68, 630000);

  // --- A QDRO
  const qA = (husbP-wifeP)/1.52;
  P('A QDRO notional', qA, 32231.58);
  P('A each w/ bonus', (wifeP+husbP)/2 + 45000*0.76/2, 654604);

  // --- A2 deferred joint sale
  const taxHer = 117000*0.15, taxHim = 117000*0.188;
  P('A2 her tax', taxHer, 17550); P('A2 his tax', taxHim, 21996);
  const tA2 = taxHer+taxHim;
  P('A2 total tax', tA2, 39546);
  const netA2 = 1100000-costs-400000-tA2;
  P('A2 net proceeds', netA2, 594454); P('A2 each', netA2/2, 297227);
  const estA2 = netA2 + 304000 + 288000 + 100000 + 40000 + 34200;
  P('A2 estate', estA2, 1360654); P('A2 half', estA2/2, 680327);
  const baseCashAll = netA2/2 + 100000 + 144000 + 20000 + 17100;
  P('A2 wife base (cash ALL)', baseCashAll, 578327);
  P('A2 QDRO (cash all)', (estA2/2-baseCashAll)/0.76, 134210.53);
  const baseCashHalf = netA2/2 + 50000 + 144000 + 20000 + 17100;
  P('A2 wife base (cash 50/50)', baseCashHalf, 528327);
  P('A2 QDRO (cash 50/50)', (estA2/2-baseCashHalf)/0.76, 200000);
  // conservative NIIT sensitivity: her 18.8% too
  const tA2c = 2*taxHim, netA2c = 1100000-costs-400000-tA2c;
  P('A2 conservative total tax', tA2c, 43992); P('A2 conservative each', (netA2c+304000+288000+100000+40000+34200)/2, 678104);

  // --- B immediate joint sale
  const taxB = (gain-500000)*0.188;
  P('B tax', taxB, 43992);
  const netB = 1100000-costs-400000-taxB;
  P('B net', netB, 590008); P('B each', netB/2, 295004);
  const estB = netB+304000+288000+100000+40000+34200;
  P('B estate', estB, 1356208); P('B half', estB/2, 678104);
  P('B wife base (cash ALL)', netB/2+100000+144000+20000+17100, 576104);
  P('B QDRO (cash all)', (estB/2-(netB/2+100000+144000+20000+17100))/0.76, 134210.53);
  P('B QDRO (cash 50/50)', (estB/2-(netB/2+50000+144000+20000+17100))/0.76, 200000);
  P('A2-B per side', estA2/2-estB/2, 2223); P('A2-B tax saving', taxB-tA2, 4446);
  P('B vs keep-alone value', netB-543008, 47000);

  // --- C
  P('C wife', 0.55*estB, 745914.4); P('C husband', 0.45*estB, 610293.6);

  // --- child support
  const net = g=>g*0.78;
  const hn45 = net(213000/12-2000), wn = net(6000+2000);
  P('husb net 45k', hn45, 12285); P('wife net', wn, 6240);
  P('combined 45k', hn45+wn, 18525);
  P('share 45k', 3050*hn45/(hn45+wn), 2022.63);
  const hn40 = net(208000/12-2000), hn50 = net(218400/12-2000);
  P('husb net 40k', hn40, 11960); P('comb 40k', hn40+wn, 18200);
  P('share 40k', 3050*hn40/(hn40+wn), 2004.29);
  P('husb net 50.4k', hn50, 12636); P('comb 50.4k', hn50+wn, 18876);
  P('share 50.4k', 3050*hn50/(hn50+wn), 2041.74);
  const hnSal = net(168000/12-2000);
  P('husb net salary-only', hnSal, 9360); P('comb salary-only', hnSal+wn, 15600);
  P('share salary-only', 3050*hnSal/(hnSal+wn), 1830);
  P('understatement', 2022.63-1830, 192.63);
  P('x12', (2022.63-1830)*12, 2311.56); P('x72', (2022.63-1830)*72, 13869.36); P('x84', (2022.63-1830)*84, 16180.92);

  // --- refinance / mortgage
  const r0=0.061/12, n=288;
  const pmt = P0=> P0*r0/(1-Math.pow(1+r0,-n));
  P('P&I 400k', pmt(400000), 2648.15);
  P('first-month interest', 400000*r0, 2033.33);
  P('44.1%', 100*pmt(400000)/6000, 44.1);
  P('26.4%', 100*pmt(400000)/10023, 26.4);
  P('33.0%', 100*pmt(400000)/8023, 33.0);
  let bal=400000, paidI=0; for(let i=0;i<36;i++){const i0=bal*r0; bal=pmt(400000)-i0+bal;}
  P('balance after 36', bal, 375779); P('principal paydown', 400000-bal, 24221);

  // --- appreciation illustration
  const price3 = 1100000*Math.pow(1.03,3);
  P('price +3%/3yr', price3, 1202000);
  const g3 = price3-price3*0.06-300000, taxEach3 = (g3-500000)/2;
  P('gain', g3, 829880); P('taxable each', taxEach3, 164940);
  P('tax total (both 18.8%)', 2*taxEach3*0.188, 62017);

  // misc
  P('bonus after-tax', 45000*0.76, 34200);
  P('YTD excess', 146212-119000, 27212); P('unexplained beyond 25200', 27212-25200, 2012);
  P('112% bonus', 45000*1.12, 50400);
  return out.join('\n');
})();

