return (function(){
  const r0=0.061/12, n=288, P=400000;
  const pmt = P*r0/(1-Math.pow(1+r0,-n));
  let bal=P;
  for(let i=0;i<36;i++){ const interest = bal*r0; bal = bal + interest - pmt; }  // correct recurrence
  return {pmt: pmt.toFixed(2), firstInterest:(P*r0).toFixed(2), bal36: bal.toFixed(0), paydown:(P-bal).toFixed(0)};
})();

